//! 🧪️ One caller work loan observes actual storage and validation effects across nested decoder scopes.
use super::*;
struct Loan{remaining:u64,calls:u64}
impl OriginalWorkRecipient for Loan{fn admits<'a>(&mut self,quote:OriginalWorkQuote<'a>,observed:u64,additional:u64)->OriginalWorkQuoteComplete<'a>{quote.complete((||{self.calls+=1;Ok(observed.checked_add(additional).is_some_and(|total|total<=self.remaining))})())}}
#[test]fn actual_work_loan_denial_nested_effect_and_failure_keep_one_original_baseline(){
 let f:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let mut callback=|_|true;let mut native=NativeDecodeControl::new(f["stock"]["capacityBytes"].as_u64().unwrap()as usize,&mut callback);
 assert!(native.prepare_work(1).is_err());assert_eq!(native.actual_work(),0);let mut denied=Loan{remaining:0,calls:0};let mut denied_issuer=OriginalWorkActionIssuer::new();let mut denied_loan=denied_issuer.loan(&mut denied);native.with_work_recipient(&mut denied_loan,|native|{assert!(!native.prepare_work(1)?);assert_eq!(native.actual_work(),0);Ok::<_,ValueError>(())}).unwrap();
 let mut loan=Loan{remaining:f["stock"]["fuel"].as_u64().unwrap(),calls:0};let mut issuer=OriginalWorkActionIssuer::new();let mut work_loan=issuer.loan(&mut loan);let mut body=Vec::<u8>::new();let result=native.with_work_recipient(&mut work_loan,|native|{
  assert!(native.prepare_work(1)?);body.try_reserve_exact(2).map_err(|_|ValueError::literal(ValueRefusalKind::AllocationFailed,"actual work law allocation failed"))?;native.commit_work(1)?;
  let mut observer=|_|true;native.scoped_observer(&mut observer,|native|{assert!(native.prepare_work(1)?);body.extend_from_slice(&[3,7]);native.commit_work(1)?;Ok::<_,ValueError>(())})?;
  let mut replacement=Loan{remaining:100,calls:0};let mut replacement_issuer=OriginalWorkActionIssuer::new();let mut replacement_loan=replacement_issuer.loan(&mut replacement);assert!(native.with_work_recipient(&mut replacement_loan,|_|Ok::<_,ValueError>(())).is_err());
  assert!(native.prepare_work(1)?);let result=std::str::from_utf8(&[255]);native.commit_work(1)?;assert!(result.is_err());assert_eq!(body,serde_json::from_value::<Vec<u8>>(f["body"].clone()).unwrap());assert!(native.prepare_work(1)?);drop(std::mem::take(&mut body));native.commit_work(1)?;assert!(!native.prepare_work(1)?);Err::<(),_>(ValueError::literal(ValueRefusalKind::InvalidValue,"actual UTF-8 probe failed"))
 });drop(work_loan);assert!(result.is_err());assert_eq!(native.actual_work(),f["expected"]["work"].as_u64().unwrap());assert_eq!(loan.remaining,4);assert!(body.is_empty());assert_eq!(native.actual_work(),4);
}

#[test]fn original_work_scope_preserves_pending_reservation_on_unwind(){let mut observer=|_|true;let mut native=NativeDecodeControl::new(0,&mut observer);let mut loan=Loan{remaining:1,calls:0};let mut issuer=OriginalWorkActionIssuer::new();let mut work_loan=issuer.loan(&mut loan);let panic=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||native.with_work_recipient(&mut work_loan,|native|{assert!(native.prepare_work(1)?);panic!("fixture unwinds before effect");#[allow(unreachable_code)]Ok::<_,ValueError>(())})));assert!(panic.is_err());assert_eq!(native.pending_work(),1);assert_eq!(native.actual_work(),0);drop(work_loan);let mut work_loan=issuer.loan(&mut loan);native.with_work_recipient(&mut work_loan,|native|native.cancel_work()).unwrap();drop(work_loan);assert_eq!(native.pending_work(),0);assert_eq!(loan.calls,1);}

/// 🪢️ A held original work reservation survives continuation and rejects a foreign issuer.
#[test]
fn original_work_reservation_rebinds_only_its_source_issuer(){
 let row:serde_json::Value=serde_json::from_str(include_str!("../recovery.json")).unwrap();let held=row["held"].as_u64().unwrap();let actual=row["actual"].as_u64().unwrap();let mut observer=|_|true;let mut native=NativeDecodeControl::new(0,&mut observer);let mut issuer=OriginalWorkActionIssuer::new();let mut owner=Loan{remaining:held,calls:0};{let mut loan=issuer.loan(&mut owner);let panic=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||native.with_work_recipient(&mut loan,|native|{assert!(native.prepare_work(held)?);panic!("actual source unwinds with held work");#[allow(unreachable_code)]Ok::<_,ValueError>(())})));assert!(panic.is_err());}assert!(issuer.has_pending_work());{let mut other_observer=|_|true;let mut other=NativeDecodeControl::new(0,&mut other_observer);let mut loan=issuer.loan(&mut owner);other.with_work_recipient(&mut loan,|other|{assert!(!other.has_pending_work());Ok::<_,ValueError>(())}).unwrap();}let receipt=native.pause().unwrap();assert!(crate::retirement::RetireOwned::retirement_birth_bytes(&receipt).is_none());let mut native=NativeDecodeControl::resume(receipt,&mut observer).unwrap();let mut foreign=Loan{remaining:held,calls:0};let mut foreign_issuer=OriginalWorkActionIssuer::new();{let mut foreign_loan=foreign_issuer.loan(&mut foreign);assert_eq!(native.with_work_recipient(&mut foreign_loan,|_|Ok::<_,ValueError>(())).is_err(),row["foreignRejected"].as_bool().unwrap());}{let mut loan=issuer.loan(&mut owner);native.with_work_recipient(&mut loan,|native|native.commit_work(actual)).unwrap();}assert_eq!(native.actual_work(),actual);assert!(!issuer.has_pending_work());assert_eq!(owner.calls,row["grantCalls"].as_u64().unwrap());
}

/// 🧳️ The original forwarded receipt retains an interrupted reservation when its caller unwinds.
#[test]
fn forwarded_receipt_survives_original_work_unwind(){use crate::native_decoding::{NativeDecodeAllocationIssuer,NativeDecodeRetirementRecipient,NativeForwardedDecodeFrame};let mut observer=|_|true;let mut port=|_|Ok(());let mut allocation_issuer=NativeDecodeAllocationIssuer::new();let mut allocation=allocation_issuer.loan(&mut port);let mut retirement=NativeDecodeRetirementRecipient::new();let mut receipt=None;let mut issuer=OriginalWorkActionIssuer::new();let mut backend=Loan{remaining:3,calls:0};let mut loan=issuer.loan(&mut backend);let interrupted=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||{let mut frame=NativeForwardedDecodeFrame::begin(&mut receipt,0,&mut observer,&mut allocation,&mut retirement).unwrap();frame.control().with_work_recipient(&mut loan,|control|{assert!(control.prepare_work(3)?);panic!("original forwarded callback interrupted");#[allow(unreachable_code)]Ok::<_,ValueError>(())}).unwrap()}));assert!(interrupted.is_err());let saved=receipt.take().unwrap();assert!(saved.has_pending_work());let mut control=crate::native_decoding::NativeForwardedDecodeControl::rebind(saved,&mut observer,&mut allocation,&mut retirement).ok().unwrap();control.with_work_recipient(&mut loan,|control|control.commit_work(3)).unwrap();assert_eq!(control.actual_work(),3);let receipt=control.detach().ok().unwrap();assert!(!receipt.has_pending_work());}

/// 📣️ A started original work quote survives unwind without a second callback.
#[test]
fn original_work_quote_panic_requires_same_issuer_resolution(){
 struct Interrupt{calls:u64}impl OriginalWorkRecipient for Interrupt{fn admits<'a>(&mut self,quote:OriginalWorkQuote<'a>,_:u64,_:u64)->OriginalWorkQuoteComplete<'a>{self.calls+=1;let completed=quote.complete(Ok(true));std::hint::black_box(&completed);panic!("original quote interrupted after actual reply")}}let row:serde_json::Value=serde_json::from_str(include_str!("../recovery.json")).unwrap();assert_eq!(row["quotePending"].as_bool(),Some(true));let held=row["held"].as_u64().unwrap();let mut observer=|_|true;let mut control=NativeDecodeControl::new(0,&mut observer);let mut issuer=OriginalWorkActionIssuer::new();let mut source=Interrupt{calls:0};{let mut loan=issuer.loan(&mut source);let panic=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||control.with_work_recipient(&mut loan,|control|control.prepare_work(held))));assert!(panic.is_err());}assert!(control.work_quote_pending());let receipt=control.pause().unwrap();assert!(crate::retirement::RetireOwned::retirement_birth_bytes(&receipt).is_none());let mut control=NativeDecodeControl::resume(receipt,&mut observer).unwrap();{let mut loan=issuer.loan(&mut source);control.with_work_recipient(&mut loan,|control|{assert_eq!(control.recover_work_quote()?,Some(true));control.commit_work(held)}).unwrap();}assert_eq!(control.actual_work(),held);assert_eq!(source.calls,row["grantCalls"].as_u64().unwrap());
}

/// 📬️ A refused consuming pause returns the actual control and pending original work intact.
#[test]
fn original_work_refused_pause_returns_the_same_pending_control(){
 let row:serde_json::Value=serde_json::from_str(include_str!("../recovery.json")).unwrap();let held=row["held"].as_u64().unwrap();let mut observer=|_|true;let mut retirement=crate::NativeDecodeRetirementRecipient::new();let mut native=NativeDecodeControl::new(0,&mut observer);native.install_retirement_recipient(&mut retirement).unwrap();let mut issuer=OriginalWorkActionIssuer::new();let mut owner=Loan{remaining:held,calls:0};{let mut loan=issuer.loan(&mut owner);native.with_work_recipient(&mut loan,|native|{assert!(native.prepare_work(held)?);Ok::<_,ValueError>(())}).unwrap();}let(_error,mut native)=native.pause().unwrap_err();assert!(native.has_pending_work());{let mut loan=issuer.loan(&mut owner);native.with_work_recipient(&mut loan,|native|native.commit_work(held)).unwrap();}assert_eq!(native.actual_work(),held);assert_eq!(owner.calls,row["grantCalls"].as_u64().unwrap());
}

#[test]fn issuer_birth_quotes_only_initialized_fields(){use crate::native_decoding::{NativeDecodeAllocationIssuer,OriginalWorkActionIssuer,NativeConstructionRecipientIssuer};let rows:serde_json::Value=serde_json::from_str(include_str!("🧬️issuer.json")).unwrap();for(name,bytes)in [("decodeAllocation",NativeDecodeAllocationIssuer::birth_bytes()),("decodeWork",OriginalWorkActionIssuer::birth_bytes()),("decodeConstruction",NativeConstructionRecipientIssuer::birth_bytes())]{let row=rows.as_array().unwrap().iter().find(|row|row["name"]==name).unwrap();assert_eq!(bytes,row["birthBytes"].as_u64().unwrap()as usize)}}

/// 🧮️ Independent reservations from the same source retain distinct original actions.
#[test]
fn original_work_issuer_tracks_multiple_independent_reservations(){
 let row:serde_json::Value=serde_json::from_str(include_str!("../recovery.json")).unwrap();let mut issuer=OriginalWorkActionIssuer::new();let mut source=Loan{remaining:4,calls:0};let mut first_callback=|_|true;let mut second_callback=|_|true;let mut first=NativeDecodeControl::new(0,&mut first_callback);let mut second=NativeDecodeControl::new(0,&mut second_callback);{let mut loan=issuer.loan(&mut source);first.with_work_recipient(&mut loan,|control|{assert!(control.prepare_work(1)?);Ok::<_,ValueError>(())}).unwrap();}{let mut loan=issuer.loan(&mut source);second.with_work_recipient(&mut loan,|control|{assert!(control.prepare_work(1)?);Ok::<_,ValueError>(())}).unwrap();}assert_eq!(issuer.outstanding(),row["parallelReservations"].as_u64().unwrap()as usize);{let mut loan=issuer.loan(&mut source);first.with_work_recipient(&mut loan,|control|control.commit_work(1)).unwrap();}assert_eq!(issuer.outstanding(),1);{let mut loan=issuer.loan(&mut source);second.with_work_recipient(&mut loan,|control|control.commit_work(1)).unwrap();}assert_eq!(issuer.outstanding(),0);assert_eq!((first.actual_work(),second.actual_work()),(1,1));assert_eq!(source.calls,2);
}
